<!doctype html>
<html lang="ru">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="robots" content="noindex,nofollow,noarchive">
    <title>{{ $title ?? 'Онлайн-предложение KOTLOV.BY' }}</title>
    <style>
        :root{color-scheme:light;--red:#dc4646;--red-dark:#b63434;--ink:#171717;--muted:#6b7280;--line:#e5e7eb;--soft:#f7f7f8;--ok:#147a45;--warn:#a85f00}
        *{box-sizing:border-box}body{margin:0;background:#f2f3f5;color:var(--ink);font-family:Inter,Arial,sans-serif;line-height:1.5}.wrap{width:min(1120px,calc(100% - 32px));margin:0 auto}.top{background:#171719;color:#fff;border-bottom:4px solid var(--red)}.top .wrap{display:flex;align-items:center;justify-content:space-between;min-height:76px}.brand{font-size:22px;font-weight:900;letter-spacing:.04em}.brand span{color:var(--red)}.secure{font-size:13px;color:#c8c8cc}.card{background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:0 8px 30px rgba(0,0,0,.06)}main.wrap{padding:30px 0 60px}.hero{padding:28px;margin-bottom:20px}.eyebrow{font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:var(--red)}h1{font-size:clamp(25px,4vw,40px);line-height:1.1;margin:8px 0 12px}.meta{display:flex;gap:10px 24px;flex-wrap:wrap;color:var(--muted)}.status{display:inline-flex;padding:6px 11px;border-radius:999px;background:#fff1f1;color:var(--red-dark);font-size:13px;font-weight:800}.grid{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:20px}.section{padding:24px;margin-bottom:20px}.section h2{margin:0 0 18px;font-size:21px}.item{display:grid;grid-template-columns:112px minmax(0,1fr) auto;gap:18px;padding:20px 0;border-top:1px solid var(--line)}.item:first-of-type{border-top:0;padding-top:0}.item-image{width:112px;height:112px;object-fit:contain;border-radius:12px;border:1px solid var(--line);background:#fff}.item h3{margin:0 0 5px;font-size:17px}.sku,.small{font-size:13px;color:var(--muted)}.price{text-align:right;white-space:nowrap}.price strong{display:block;font-size:18px}.specs{display:grid;grid-template-columns:1fr 1fr;gap:5px 18px;margin-top:13px;font-size:13px}.specs div{display:flex;justify-content:space-between;gap:12px;border-bottom:1px dotted #d1d5db;padding:3px 0}.specs span:first-child{color:var(--muted)}.summary{padding:24px;position:sticky;top:16px}.sum-row{display:flex;justify-content:space-between;gap:16px;padding:8px 0}.total{margin-top:10px;padding-top:14px;border-top:2px solid var(--red);font-size:22px;font-weight:900}.button{display:inline-flex;align-items:center;justify-content:center;width:100%;border:0;border-radius:11px;padding:13px 16px;margin-top:10px;background:var(--red);color:#fff;text-decoration:none;font:inherit;font-weight:800;cursor:pointer}.button:hover{background:var(--red-dark)}.button.secondary{background:#fff;color:var(--ink);border:1px solid #cfd2d7}.button.danger{background:#fff;color:#a22525;border:1px solid #efb1b1}.notice{padding:14px 16px;border-radius:11px;margin-bottom:18px;background:#e9f8ef;color:var(--ok)}.notice.error{background:#fff1f1;color:#9b2424}.terms{display:grid;grid-template-columns:1fr 1fr;gap:20px}.terms strong{display:block;margin-bottom:5px}.action-box{margin-top:14px;border:1px solid var(--line);border-radius:12px;padding:12px}details summary{cursor:pointer;font-weight:800}textarea,select,input[type=text]{width:100%;border:1px solid #cfd2d7;border-radius:9px;padding:11px;margin-top:10px;font:inherit}.confirm{display:flex;gap:9px;align-items:flex-start;font-size:13px;margin:12px 0}.center{max-width:600px;margin:7vh auto;padding:32px;text-align:center}.center p{color:var(--muted)}.code{font-size:28px;text-align:center;letter-spacing:.3em}.footer{padding:24px 0;text-align:center;color:var(--muted);font-size:13px}
        @media(max-width:800px){.grid{grid-template-columns:1fr}.summary{position:static}.item{grid-template-columns:82px minmax(0,1fr)}.item-image{width:82px;height:82px}.price{grid-column:2;text-align:left}.specs,.terms{grid-template-columns:1fr}.secure{display:none}.hero,.section,.summary{padding:20px}.wrap{width:min(100% - 20px,1120px)}}
    </style>
</head>
<body>
<header class="top"><div class="wrap"><div class="brand">KOTLOV<span>.BY</span></div><div class="secure">Защищённое коммерческое предложение</div></div></header>
<main class="wrap">@yield('content')</main>
<footer class="footer">KOTLOV.BY · Отопление, водоснабжение, профессиональный подбор</footer>
</body>
</html>
